def toposort(nodes: list[int], edges: list[tuple[int, int]]) -> list[int]:
    if not nodes:
        return []

    # Build adjacency list and in-degree count, handling duplicates
    adj = {n: set() for n in nodes}
    in_degree = {n: 0 for n in nodes}

    for u, v in edges:
        if u not in adj or v not in adj:
            continue
        if v not in adj[u]:
            adj[u].add(v)
            in_degree[v] += 1

    # Check for self-loops (cycle)
    for n in nodes:
        if n in adj[n]:
            raise ValueError("Cycle detected")

    # Use a sorted list to get lexicographically smallest
    # We'll use a simple approach: maintain a sorted list of available nodes
    available = sorted([n for n in nodes if in_degree[n] == 0])

    result = []

    while available:
        # Pick the smallest available node
        node = available.pop(0)
        result.append(node)

        # Process neighbors
        for neighbor in sorted(adj[node]):
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                # Insert into available maintaining sorted order
                # Binary search for insertion point
                lo, hi = 0, len(available)
                while lo < hi:
                    mid = (lo + hi) // 2
                    if available[mid] < neighbor:
                        lo = mid + 1
                    else:
                        hi = mid
                available.insert(lo, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result
